        status = info['status']
        if status in ('PASS', 'FAIL'):
            print(f"  n={n}: {status:4s}  anti-sym failures={info['asym_failures']}  "
                  f"Jacobi failures={info['jacobi_failures']}/{info['total_triples']} triples")
        else:
            print(f"  n={n}: {status}")
    if all_pass:
        print("\nOVERALL RESULT: ALL CHECKS PASSED ✓")
    else:
        print("\nOVERALL RESULT: FAILURES DETECTED — root cause analysis required")
    return 0 if all_pass else 1


if __name__ == '__main__':
    sys.exit(main())
